  add('practiceMinutes',t.practice,'number');add('qualifyingMinutes',t.qualifying,'number');add('raceMinutes',t.race,'number',true);add('maxDrivers',t.maxDrivers,'number',true);add('registered',t.registered,'number');add('carClass',t.carClass);add('imageUrl',t.image,'url',values.competition!=='ATXS');add('simgridUrl',t.register,'url',values.competition!=='ATXS');
